// ── Lookup function used by the AI modal ──────────────────────
function getKDEFallback(question) {
  // Direct match
  if (KDE_EXPLANATIONS[question]) return KDE_EXPLANATIONS[question];
  // Fuzzy match — find closest question (first 60 chars)
  const qLower = question.toLowerCase().trim();
  const keys = Object.keys(KDE_EXPLANATIONS);
  const match = keys.find(k => {
    const kLower = k.toLowerCase();
    return kLower.includes(qLower.substring(0, 40)) || qLower.includes(kLower.substring(0, 40));
  });
  return match ? KDE_EXPLANATIONS[match] : null;
}
